#!/usr/bin/env python3
from pwn import *
import time

# Configure the connection
host = "android-dropper.csaw.io"
port = 3000

def generate_sequence(seq_type, length=30):
    if seq_type == "square":
        return [i*i for i in range(length)]
    elif seq_type == "linear":
        return list(range(length))
    elif seq_type == "negative_square":
        return [-(i*i) for i in range(length)]
    elif seq_type == "alternating_square":
        return [(i*i) if i % 2 == 0 else -(i*i) for i in range(length)]
    elif seq_type == "cube":
        return [i**3 for i in range(length)]
    return []

def test_sequence(r, seq_type):
    print(f"\nTesting {seq_type} sequence:")
    sequence = generate_sequence(seq_type)

    print(f"Sending sequence: {sequence[:5]}...")

    # Send each number in the sequence
    for num in sequence:
        r.sendline(str(num).encode())

        # Get response
        try:
            response = r.recvline().decode().strip()
            print(f"Response: {response}")

            # Check for flag format
            if "csawctf{" in response:
                print("Found flag!")
                return response

        except EOFError:
            print("Connection closed by server")
            return None

    # Try to get any final response
    try:
        final_response = r.recvall(timeout=2).decode()
        print(f"Final response: {final_response}")
        return final_response
    except:
        return None

def main():
    # List of sequences to try
    sequences = ["square", "linear", "negative_square", "alternating_square", "cube"]

    for seq_type in sequences:
        # Create new connection for each sequence
        r = remote(host, port)

        print(f"\n{'='*50}")
        print(f"Testing sequence type: {seq_type}")
        print(f"{'='*50}")

        result = test_sequence(r, seq_type)

        # Close connection
        r.close()

        # Small delay between attempts
        time.sleep(1)

        if result and "csawctf{" in result:
            print(f"Found flag in {seq_type} sequence!")
            break

if __name__ == "__main__":
    main()

